joi_block.script:
hold_ticks := 0
if (all(#PresenceSensor #Study).presenceSensor_presence == false) {
hold_ticks = hold_ticks + 1
    if (hold_ticks >= 900) {
(#Light).light_moveToBrightness(20, 0)
        delay(10 MIN)
(#Light).switch_off()
        break
}
}
else {
hold_ticks = 0
}

